def get_first_n_squares_gen(n):

    for i in range(n):
        yield i * i

print([square for square in get_first_n_squares_gen(5)])  # 0, 1, 4, 9, 16

def get_first_n_squares(n):

    squares = []
    for i in range(n):
        squares.append(i * i)
    return squares

print(get_first_n_squares(5))  # [0, 1, 4, 9, 16]

